BEGIN;

VALUES ('002078.SZ', '太阳纸业', '深圳证券交易所', '造纸（林浆纸一体化）', '人民币', '浆纸销量（纸＋外销浆）', '万吨',
        '综合吨收入（营业收入÷销量）', '万元/吨（0.40＝4000 元/吨）', FALSE, '中国浆纸一体化龙头之一。山东（兖州、邹城、颜店）、广西（北海、南宁）、老挝三大基地，2025 年末浆纸产能超过 1400 万吨，2026 年颜店 70 万吨包装纸、60 万吨化学浆投产后约 1600 万吨（含自用浆）。产品：文化纸（双胶纸、铜版纸）、包装纸（牛皮箱板纸、瓦楞纸）、生活用纸、特种纸，以及溶解浆、化学浆、化机浆。
怎么赚钱：收入＝浆纸销量×综合吨收入；利润来自“吨纸价差”＝纸价−木浆/木片/废纸−能源−化工−物流。纸是大宗品，公司没有定价权；它的优势在成本：自制浆（自给率六成以上）比外购便宜、热电联产让能源便宜、老挝林地提供便宜木片。所以它在行业底部仍赚钱，但赚多少由纸浆周期决定。
本质：会算账的重资产周期制造商。价值取决于两件事：跨周期的吨利有多厚，以及扩张性资本开支什么时候停下来、变成股东能拿到的现金。', '主要风险：纸价与浆价错配、行业新增产能压价、文化纸需求长期下滑、扩张不停导致自由现金流长期为负、净负债上升、第一大客户为关联方（集团白卡纸业务）、多个税收优惠 2026—2033 年陆续到期。')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, exchange = EXCLUDED.exchange, industry = EXCLUDED.industry,
  currency = EXCLUDED.currency, volume_label = EXCLUDED.volume_label, volume_unit = EXCLUDED.volume_unit,
  price_label = EXCLUDED.price_label, price_unit = EXCLUDED.price_unit, profile = EXCLUDED.profile, notes = EXCLUDED.notes;

VALUES ('002078.SZ.PRICE', '太阳纸业收盘价', '元', '行情', (SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '腾讯行情（自动采集）；2025-10-20—2026-10-21 日线由腾讯 K 线接口一次性补齐（不复权）', '交易日', 0, 200, '股价只进入对比层，不进入经营假设。')
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, unit = EXCLUDED.unit, category = EXCLUDED.category, company_id = EXCLUDED.company_id,
  source_name = EXCLUDED.source_name, frequency = EXCLUDED.frequency, valid_min = EXCLUDED.valid_min, valid_max = EXCLUDED.valid_max, notes = EXCLUDED.notes;

UPDATE vi_company_base SET price_metric_id = (SELECT id FROM vi_metric_base WHERE code = '002078.SZ.PRICE') WHERE code = '002078.SZ';

DELETE FROM vi_lnk_company_macro_metrics WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ');
SELECT (SELECT id FROM vi_company_base WHERE code = '002078.SZ'), id FROM vi_metric_base WHERE code IN ('SP.SHFE.WIND', 'SP.SHFE.SINA');

SELECT '太阳纸业股价（腾讯行情）', (SELECT id FROM vi_metric_base WHERE code = '002078.SZ.PRICE'), 'https://qt.gtimg.cn/q=sz002078', 'tencent_quote', 'sz002078', TRUE, 7, '返回 GBK 编码，名称会乱码但不影响按“~”分段解析。'
WHERE NOT EXISTS (SELECT 1 FROM vi_collector_base WHERE name = '太阳纸业股价（腾讯行情）');
