INSERT INTO vi_source_base (company_id, title, source_type, publisher, publish_date, url, reliability, verify_status, retrieved_on, summary, limitations) VALUES
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '太阳纸业 2025 年年度报告', '定期报告', '太阳纸业', '2026-04-11', 'https://file.finance.sina.com.cn/211.154.219.97:9494/MRGG/CNSESZ_STOCK/2026/2026-4/2026-04-11/12078959.PDF', '一级·法定披露', '已读原文', '2026-07-26', '营业收入 391.92 亿元（−3.77%）；归母净利润 32.51 亿元（+4.82%）；纸 799 万吨、外销浆 130 万吨；分产品收入与毛利率；各子公司所得税率与税收优惠到期时间；前五大客户 21.87%，第一大客户 11.06% 为关联方。', '本地 PDF：~/Desktop/二级市场/价值投资/太阳纸业/原始资料/S01。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '太阳纸业 2024 年年度报告', '定期报告', '太阳纸业', '2025-04-10', 'https://file.finance.sina.com.cn/211.154.219.97:9494/MRGG/CNSESZ_STOCK/2025/2025-4/2025-04-10/10858837.PDF', '一级·法定披露', '已读原文', '2026-07-26', '纸 751 万吨、浆 146 万吨（外销）；箱板纸收入 109.31 亿元。', NULL),
