INSERT INTO vi_fit_score_base (company_id, dimension, score, rationale, counter, sort) VALUES
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '长坡', 3, '包装纸需求随消费与“以纸代塑”增长，特种纸有新品类；公司还在扩产与提高自给率。', '大宗纸总需求增速约等于经济增速或更低；文化纸需求长期下降；新增产能多。', 1),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '厚雪', 2, '行业利润池薄：2025 年同业毛利率 6%—14%，多家亏损；公司靠成本做到约 15%—16%。', '龙头集中度在提升（铜版纸 CR4 约 89%、箱板纸 CR5 约 42%），落后产能出清后利润池可能变厚。', 2),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '慢变', 3, '造纸技术与需求变化慢，竞争规则清楚。', '周期剧烈（浆价、纸价、产能投放）；文化纸被电子化替代。', 3),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '护城河', 3, '自制浆与林浆纸一体化是可度量的成本优势（真实壁垒）；能源、林地、执行力是局部优势。', '没有定价权；规模、税收优惠、溶解浆双寡头是伪壁垒；同业在追赶一体化。', 4),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '再投资', 2, 'ROE 约 11%，仍高于约 7.6% 的资本成本，扩张在创造价值。', 'ROE 逐年下降；2019—2025 年股东自由现金近似为零，增量资本回报粗算约 4%。', 5),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '财务质量', 3, '利润是真现金（经营现金流÷净利约 1.5—1.9 倍），会计口径清楚。', '净负债÷EBITDA 约 2.6 倍、短债占比高；分红实际靠借款支付。', 6),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '治理配置', 3, '民营执行力强、激励到位，分红稳定（26%—27%）。', '偏好扩张、派息率低；第一大客户为关联方（11%），关联交易要盯。', 7),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '可估值性', 3, '量、价、成本结构清楚，可以建模。', '价值约七成来自终值，依赖扩张结束后派息率提高的判断；纸价周期让单年利润波动大。', 8);
