INSERT INTO vi_scenario_base (model_id, name, is_base, sort, volume_factor, price_factor, cost_factor, discount_rate, terminal_growth, nature, description) VALUES
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), '悲观', FALSE, 1, 0.97, 0.96, 0.975, 0.086, 0.005, '周期低迷：利润率长期停在 2022—2023 年水平', '销量 −3%、吨收入 −4%、付现成本 −2.5%（成本大部分随销量变化）→ EBITDA 率约 15.2%（2022 年 15.1%、2023 年 15.8%）；折现率 8.6%，永续增长 0.5%。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), '基准', TRUE, 2, 1, 1, 1, NULL, 0.015, '无纸价回升；已宣布项目按期投产', '逐年假设原样；折现率＝无风险利率＋风险溢价（7.6%），永续增长 1.5%。利润比卖方一致预期低 2%—9%（不假设提价）。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), '乐观', FALSE, 3, 1.03, 1.01, 1.015, 0.071, 0.025, '纸价修复、新产能顺利爬坡', '销量 +3%、吨收入 +1%、付现成本 +1.5% → EBITDA 率约 21%（接近 2019—2020 年）；折现率 7.1%，永续增长 2.5%。');
INSERT INTO vi_forecast_base (model_id, year, volume, price, cash_cost, depreciation, other_contrib, tax_rate, minority_share, payout, net_borrowing, cost_of_debt, noncash_gain_deduct, investee_cash_div, other_cash_adj, wc_increase, maint_capex, growth_capex, min_cash_topup, operating_status, cash_status, note) VALUES
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2026, 1065, 0.402, 349.78, 29.0, 0.0, 0.14, 0.003, 0.27, 12.5, 0.027, 0.3, 0.1, 5.2, 3.6, 20, 50, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 18.3%；吨付现成本约 3284 元。上半年实际：营收 208.62、归母 19.51；下半年 PM47、颜店浆线投产。归母净利约 37.5 亿元（一致预期 38.0，激励门槛扣非 35.1）。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2027, 1115, 0.402, 363.96, 31.0, -1.0, 0.15, 0.003, 0.27, 0.5, 0.027, 0.3, 0.1, 2.0, 2.0, 22, 38, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 18.8%；吨付现成本约 3264 元。PM47 满年；南宁项目 2027Q4 投完并试产；激励费用全年约 2 亿元。归母约 39.3 亿元（一致预期 41.9，激励门槛 38.3）。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2028, 1150, 0.402, 374.46, 32.0, 0.1, 0.155, 0.003, 0.28, -11.5, 0.027, 0.3, 0.1, 0.9, 1.4, 24, 26, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 19.0%；吨付现成本约 3256 元。资本开支约 50 亿元（老挝新项目开工），开始还债；归母约 42.2 亿元（一致预期 46.1，激励门槛 41.5）。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2029, 1165, 0.406, 383.12, 33.0, 0.7, 0.17, 0.003, 0.3, -14, 0.027, 0.3, 0.1, 0.3, 1.1, 26, 22, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 19.0%；吨付现成本约 3289 元。南宁园区 9%→15% 税率；资本开支约 48 亿元。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2030, 1195, 0.4101, 396.96, 34.0, 1.0, 0.17, 0.003, 0.4, -16, 0.027, 0.3, 0.1, 0.0, 1.7, 28, 15, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 19.0%；吨付现成本约 3322 元。老挝新项目投产（约 +30 万吨），扩张资本回落到 15 亿元；派息率 40%。'),
((SELECT id FROM vi_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND name = '太阳纸业 DDM＋现金桥接（2025 年末基准）'), 2031, 1225, 0.4142, 410.99, 35.0, 1.0, 0.17, 0.003, 0.5, -17, 0.027, 0.3, 0.1, 0.0, 1.7, 30, 10, 0, '建议值待核验', '建议值待核验', 'EBITDA 率 19.0%；吨付现成本约 3355 元。'),
