INSERT INTO vi_lnk_judgment_metrics (judgment_id, metric_id, "createdAt", "updatedAt") SELECT x.id, (SELECT id FROM vi_metric_base WHERE company_id IS NULL AND name = '纸浆期货最新价（新浪 SP0 连续）' AND unit IS NOT DISTINCT FROM '元/吨' ORDER BY id LIMIT 1), now(), now() FROM vi_judgment_base x WHERE x.company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND x.code = 'J-M' AND (SELECT id FROM vi_metric_base WHERE company_id IS NULL AND name = '纸浆期货最新价（新浪 SP0 连续）' AND unit IS NOT DISTINCT FROM '元/吨' ORDER BY id LIMIT 1) IS NOT NULL ON CONFLICT DO NOTHING;
